import React, { useContext, useEffect, useState } from 'react';
import { Fade } from 'react-awesome-reveal';
import Tilt from 'react-parallax-tilt';
import { Container, Row, Col } from 'react-bootstrap';
import { useTranslation } from 'react-i18next';
import PortfolioContext from '../../context/context';
import Title from '../Title/Title';
import ProjectImg from '../Image/ProjectImg';

const Projects = () => {
  const { projects } = useContext(PortfolioContext);
  const { t } = useTranslation();

  const [isDesktop, setIsDesktop] = useState(false);

  useEffect(() => {
    setIsDesktop(window.innerWidth > 769);
  }, []);

  return (
    <section id="projects">
      <Container>
        <div className="project-wrapper">
          <Title title={t('projectsData.title')} />
          {projects.map(project => {
            const { id, title, infoKey, info2Key, url, repo, img } = project;

            return (
              <Row key={id}>
                <Col lg={4} sm={12}>
                  <Fade
                    direction={isDesktop ? 'left' : 'up'}
                    duration={1000}
                    delay={500}
                    triggerOnce
                  >
                    <div className="project-wrapper__text">
                      <h3 className="project-wrapper__text-title">{title || 'Project Title'}</h3>
                      <div>
                        <p>{t(infoKey)}</p>
                        <p className="mb-4">{t(info2Key)}</p>
                      </div>
                      <a
                        target="_blank"
                        rel="noopener noreferrer"
                        className="cta-btn cta-btn--hero"
                        href={url || '#!'}
                      >
                        {t('projectsData.seelive')}
                      </a>

                      {repo && (
                        <a
                          target="_blank"
                          rel="noopener noreferrer"
                          className="cta-btn text-color-main"
                          href={repo}
                        >
                          {t('projectsData.sourcecode')}
                        </a>
                      )}
                    </div>
                  </Fade>
                </Col>
                <Col lg={8} sm={12}>
                  <Fade
                    direction={isDesktop ? 'right' : 'up'}
                    duration={1000}
                    delay={1000}
                    triggerOnce
                  >
                    <div className="project-wrapper__image">
                      <a
                        href={url || '#!'}
                        target="_blank"
                        aria-label="Project Link"
                        rel="noopener noreferrer"
                      >
                        <Tilt
                          tiltMaxAngleDegrees={8}
                          perspective={1000}
                          scale={1}
                          transitionSpeed={300}
                          reset
                          transitionEasing="cubic-bezier(.03,.98,.52,.99)"
                        >
                          <div data-tilt className="thumbnail rounded">
                            <ProjectImg alt={title} filename={img} />
                          </div>
                        </Tilt>
                      </a>
                    </div>
                  </Fade>
                </Col>
              </Row>
            );
          })}
        </div>
      </Container>
    </section>
  );
};

export default Projects;
