import React, { useState } from 'react';
import { Container } from 'react-bootstrap';
import { useTranslation } from 'react-i18next';

const FLAG_FR =
  'https://res.cloudinary.com/dkyqbngya/image/upload/c_scale,w_30/v1585483466/france-flag-button-round-icon-64_uqllrc.png';
const FLAG_EN =
  'https://res.cloudinary.com/dkyqbngya/image/upload/c_scale,w_30/v1585483470/united-states-of-america-flag-button-round-xs_xgcefz.png';

const Navbar = () => {
  const { t, i18n } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);

  const toggleLang = () => {
    i18n.changeLanguage(i18n.language === 'fr' ? 'en' : 'fr');
  };

  return (
    <nav className="navbar-custom">
      <Container>
        <div className="navbar-custom__brand">
          <a href="#hero">Sandrine Cao</a>
        </div>
        <button
          className={`navbar-custom__toggle${isOpen ? ' open' : ''}`}
          aria-label="Toggle navigation"
          onClick={() => setIsOpen(o => !o)}
        >
          <span />
          <span />
          <span />
        </button>
        <ul className={`navbar-custom__links${isOpen ? ' open' : ''}`}>
          {[
            { key: 'about', href: '#about' },
            { key: 'projects', href: '#projects' },
            { key: 'contact', href: '#contact' },
          ].map(({ key, href }) => (
            <li key={key}>
              <a href={href} onClick={() => setIsOpen(false)}>
                {t(`navbar.${key}`)}
              </a>
            </li>
          ))}
          <li className="navbar-custom__flag">
            <button onClick={toggleLang} aria-label="Switch language">
              <img
                src={i18n.language === 'fr' ? FLAG_FR : FLAG_EN}
                alt={i18n.language === 'fr' ? 'French Flag' : 'US Flag'}
              />
            </button>
          </li>
        </ul>
      </Container>
    </nav>
  );
};

export default Navbar;
